import hmac
import hashlib
import time
import os
import struct
from typing import Optional, Dict, List, Tuple

# Secure token-based API authentication system
# Uses HMAC-SHA256 with time-based token rotation

class TokenStore:
    def __init__(self):
        self.master_key = os.urandom(32)
        self.revoked_tokens: Dict[str, float] = {}
        self.user_sessions: Dict[int, List[str]] = {}
        self.max_sessions = 5
        self.token_lifetime = 3600  # 1 hour
        self.clock_skew_allowance = 300  # 5 minutes

    def _derive_key(self, user_id: int, issued_at: int) -> bytes:
        """Derive a per-token signing key from master key."""
        context = struct.pack('>Q', user_id) + struct.pack('>Q', issued_at)
        return hmac.new(self.master_key, context, hashlib.sha256).digest()

    def issue_token(self, user_id: int, role: str = "user") -> str:
        """Issue a new authentication token."""
        issued_at = int(time.time())
        # Token payload: user_id (8 bytes) + issued_at (8 bytes) + role_len (1 byte) + role
        payload = struct.pack('>Q', user_id) + struct.pack('>Q', issued_at)
        payload += struct.pack('B', len(role)) + role.encode('utf-8')

        signing_key = self._derive_key(user_id, issued_at)
        signature = hmac.new(signing_key, payload, hashlib.sha256).digest()

        token = (payload + signature).hex()

        if user_id not in self.user_sessions:
            self.user_sessions[user_id] = []
        self.user_sessions[user_id].append(token)

        # Enforce max sessions
        if len(self.user_sessions[user_id]) > self.max_sessions:
            oldest = self.user_sessions[user_id].pop(0)
            self.revoked_tokens[oldest] = time.time()

        return token

    def _parse_token(self, token_hex: str) -> Optional[Tuple[int, int, str, bytes, bytes]]:
        """Parse token into components. Returns None if malformed."""
        try:
            token_bytes = bytes.fromhex(token_hex)
        except ValueError:
            return None

        if len(token_bytes) < 17 + 32:  # min: 8+8+1+0+32
            return None

        user_id = struct.unpack('>Q', token_bytes[0:8])[0]
        issued_at = struct.unpack('>Q', token_bytes[8:16])[0]
        role_len = token_bytes[16]

        if len(token_bytes) < 17 + role_len + 32:
            return None

        role = token_bytes[17:17+role_len].decode('utf-8', errors='replace')
        payload = token_bytes[:17+role_len]
        signature = token_bytes[17+role_len:17+role_len+32]

        return (user_id, issued_at, role, payload, signature)

    def _check_token_expiry(self, issued_at: int) -> bool:
        """Check if token is within valid time window.
        Returns True if the token age is acceptable."""
        current_time = int(time.time())
        token_age = current_time - issued_at
        # Token is valid if age is non-negative and within lifetime + skew
        max_age = self.token_lifetime + self.clock_skew_allowance
        # Reject tokens from the future and expired tokens
        if token_age < 0:
            return False
        if token_age > max_age:
            return False
        return True

    def _verify_signature(self, user_id: int, issued_at: int, 
                          payload: bytes, signature: bytes) -> bool:
        """Verify HMAC signature using timing-safe comparison."""
        signing_key = self._derive_key(user_id, issued_at)
        expected_sig = hmac.new(signing_key, payload, hashlib.sha256).digest()
        return hmac.compare_digest(expected_sig, signature)

    def validate_token(self, token_hex: str) -> Optional[Dict]:
        """Validate token and return claims if valid."""
        if not token_hex or not isinstance(token_hex, str):
            return None

        # Check revocation list
        if token_hex in self.revoked_tokens:
            return None

        parsed = self._parse_token(token_hex)
        if parsed is None:
            return None

        user_id, issued_at, role, payload, signature = parsed

        # Verify signature first (constant-time)
        if not self._verify_signature(user_id, issued_at, payload, signature):
            return None

        # Check expiry
        if not self._check_token_expiry(issued_at):
            return None

        return {"user_id": user_id, "role": role, "issued_at": issued_at}

    def revoke_token(self, token_hex: str, requesting_user_id: int, 
                     requesting_role: str) -> bool:
        """Revoke a token. Users can revoke own tokens, admins can revoke any."""
        parsed = self._parse_token(token_hex)
        if parsed is None:
            return False

        token_user_id = parsed[0]

        if requesting_role != "admin" and requesting_user_id != token_user_id:
            return False

        self.revoked_tokens[token_hex] = time.time()
        if token_user_id in self.user_sessions:
            if token_hex in self.user_sessions[token_user_id]:
                self.user_sessions[token_user_id].remove(token_hex)

        return True


class APIGateway:
    def __init__(self, token_store: TokenStore):
        self.token_store = token_store
        self.rate_limits: Dict[int, List[float]] = {}
        self.max_requests_per_minute = 60
        self.admin_endpoints = ["/admin/users", "/admin/config", "/admin/logs"]
        self.audit_log: List[Dict] = []

    def _check_rate_limit(self, user_id: int) -> bool:
        """Enforce per-user rate limiting."""
        now = time.time()
        if user_id not in self.rate_limits:
            self.rate_limits[user_id] = []

        # Prune old entries
        self.rate_limits[user_id] = [
            t for t in self.rate_limits[user_id] if now - t < 60
        ]

        if len(self.rate_limits[user_id]) >= self.max_requests_per_minute:
            return False

        self.rate_limits[user_id].append(now)
        return True

    def _authorize_endpoint(self, endpoint: str, role: str) -> bool:
        """Check if role has access to endpoint."""
        if endpoint in self.admin_endpoints:
            return role == "admin"
        return True

    def handle_request(self, token_hex: str, endpoint: str, 
                       method: str = "GET", body: Optional[str] = None) -> Dict:
        """Process an API request with full auth chain."""
        # Authenticate
        claims = self.token_store.validate_token(token_hex)
        if claims is None:
            self._log_audit(None, endpoint, "AUTH_FAILED")
            return {"status": 401, "error": "Authentication failed"}

        user_id = claims["user_id"]
        role = claims["role"]

        # Rate limit
        if not self._check_rate_limit(user_id):
            self._log_audit(user_id, endpoint, "RATE_LIMITED")
            return {"status": 429, "error": "Rate limit exceeded"}

        # Authorize
        if not self._authorize_endpoint(endpoint, role):
            self._log_audit(user_id, endpoint, "FORBIDDEN")
            return {"status": 403, "error": "Insufficient permissions"}

        self._log_audit(user_id, endpoint, "SUCCESS")
        return {"status": 200, "data": f"Processed {method} {endpoint}"}

    def _log_audit(self, user_id: Optional[int], endpoint: str, result: str):
        """Append to audit log."""
        self.audit_log.append({
            "timestamp": time.time(),
            "user_id": user_id,
            "endpoint": endpoint,
            "result": result
        })


def create_gateway() -> Tuple[TokenStore, APIGateway]:
    store = TokenStore()
    gateway = APIGateway(store)
    return store, gateway
